   [39]={next_id=40, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="弦枝是星源共鸣者？那按狮刃姐说的，她不应该已经被伯基索米军方收编了吗？", msg_color="", msg_size=0, talker="艾丽西亚", audio="", img="arts/ui/bg/story/storybg_14_108.jpg", video_url="", music_id="0", background_music="", model_tid={{ 1, "3102", 0, 0, 49, 175.5},{ 3, "3101_1", 0, 0, 8, 176.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 1,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
