   [201]={next_id=202, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当年的那场暴动，那场他犯下的错，是他一生的枷锁。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [202]={next_id=203, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="芙兰朵女士，时间已经刻不容缓。我已经为帝国和大统领赎罪多年，哪怕大统领仍不接受我的赎罪，就当是为了伊凡城里没能逃难的民众，也恳请你——", msg_color="", msg_size=0, talker="卫队将军", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7196", 0, 0, 27, 218}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [203]={next_id=204, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="——谢尔盖将军。", msg_color="", msg_size=0, talker="芙兰朵", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [204]={next_id=205, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="女人的声音骤然变冷，收起了那副慵懒的姿态。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [205]={next_id=206, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我不得不提醒你一句，你最好搞清楚自己的身份。", msg_color="", msg_size=0, talker="芙兰朵", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [206]={next_id=207, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你虽然挂着将军的头衔，手里握着一支卫队，但你本质上，不过是个被帝国流放到伊凡城赎罪的罪人。", msg_color="", msg_size=0, talker="芙兰朵", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [207]={next_id=208, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当年你没能压制住伊凡城的暴动，让暴徒炸毁了帝国宝贵的空天星链基站，大统领愿意让你自我流放到伊凡城做一个守城将军赎罪，已经是天大的仁慈。", msg_color="", msg_size=0, talker="芙兰朵", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [208]={next_id=209, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="将军的身体猛地一僵，当年的画面不受控制地涌上脑海，那些鲜血与痛苦的呐喊，如同一根镣铐，扼制在他的喉间。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [209]={next_id=210, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="如今伯基索米要处理的事情太多了，伊凡城的死活，在大统领的伟业面前，根本不值一提。", msg_color="", msg_size=0, talker="芙兰朵", audio="", img="arts/ui/bg/story/storybg_14_106.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7126_1", 0, 1, -46.5, 219}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
